// Activity — the "everything published, in order" list that didn't exist.
// The record's actual content lives in three different tables that never
// get shown together: pages (signed readings), pieces (editorial CMS
// content — essays, research reports, including auto-generated ones),
// and the legacy `briefs` table (sunset for new writes, old ones still
// resolve). /library only ever showed pieces; a signed reading was
// invisible there. This is the one place an operator can actually see
// what's live, in the order it went live, regardless of which pipeline
// made it.
//
// Read-only. No operator affordances here — this is an audit view, not
// a workspace; act on an item from its own page.

import { all } from "../../lib/d1";
import { type PublicEnv, resolveOperatorId } from "../data";
import { escapeAttr, escapeHtml, renderPage } from "../layout";
import { emptyState } from "./components";

interface ActivityItem {
  type: "reading" | "piece" | "brief";
  title: string;
  href: string;
  kindLabel: string;
  publishedAt: string | null;
  byline: string | null;
  autoGenerated: boolean;
}

const EDITORIAL_KINDS = [
  "essay",
  "research-report",
  "documented-record",
  "thesis",
  "synthesis",
  "brief",
];

function isAutoGenerated(tags: string): boolean {
  try {
    const parsed = JSON.parse(tags || "[]") as unknown;
    return Array.isArray(parsed) && parsed.includes("auto-research");
  } catch {
    return false;
  }
}

function formatDate(iso: string | null): string {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

export async function renderActivityPage(env: PublicEnv): Promise<string> {
  const userId = await resolveOperatorId(env.DB);

  const [readings, pieces, briefs] = userId
    ? await Promise.all([
        all<{
          slug: string;
          label: string;
          intent: string | null;
          signed_by: string | null;
          signed_at: string | null;
        }>(
          env.DB,
          `SELECT p.slug, n.label, p.intent, p.signed_by, p.signed_at
             FROM pages p JOIN nodes n ON n.id = p.subject_node_id
            WHERE p.user_id = ? AND p.signed_status IN ('signed', 'published')
            ORDER BY p.signed_at DESC`,
          [userId],
        ).catch(() => []),
        all<{
          slug: string;
          title: string;
          kind: string;
          byline: string | null;
          published_at: string | null;
          created_at: string;
          tags: string;
        }>(
          env.DB,
          `SELECT slug, title, kind, byline, published_at, created_at, tags
             FROM pieces
            WHERE user_id = ? AND kind IN (${EDITORIAL_KINDS.map(() => "?").join(",")})
              AND publication_status IN ('published', 'canonical')
            ORDER BY COALESCE(published_at, created_at) DESC`,
          [userId, ...EDITORIAL_KINDS],
        ).catch(() => []),
        all<{
          slug: string;
          title: string;
          content_type: string;
          signed_by: string | null;
          published_at: string | null;
        }>(
          env.DB,
          `SELECT slug, title, content_type, signed_by, published_at
             FROM briefs WHERE user_id = ? AND status = 'published'
            ORDER BY published_at DESC`,
          [userId],
        ).catch(() => []),
      ])
    : [[], [], []];

  const items: ActivityItem[] = [
    ...readings.map(
      (r): ActivityItem => ({
        type: "reading",
        title: r.label,
        href: `/s/${r.slug}?mode=signed`,
        kindLabel: r.intent ? `signed analysis · ${r.intent}` : "signed analysis",
        publishedAt: r.signed_at,
        byline: r.signed_by,
        autoGenerated: false,
      }),
    ),
    ...pieces.map(
      (p): ActivityItem => ({
        type: "piece",
        title: p.title,
        href: `/p/${p.slug}`,
        kindLabel: p.kind,
        publishedAt: p.published_at ?? p.created_at,
        byline: p.byline,
        autoGenerated: isAutoGenerated(p.tags),
      }),
    ),
    ...briefs.map(
      (b): ActivityItem => ({
        type: "brief",
        title: b.title,
        href: `/briefs/${b.slug}`,
        kindLabel: `brief · ${b.content_type}`,
        publishedAt: b.published_at,
        byline: b.signed_by,
        autoGenerated: false,
      }),
    ),
  ].sort((a, b) => (b.publishedAt ?? "").localeCompare(a.publishedAt ?? ""));

  const rows = items
    .map(
      (item) => `<div class="act-row${item.autoGenerated ? " act-auto" : ""}">
  <div class="act-row-head">
    <span class="act-kind">${escapeHtml(item.kindLabel)}</span>
    ${item.autoGenerated ? `<span class="act-auto-flag">AI-drafted, operator-reviewed</span>` : ""}
    ${item.publishedAt ? `<span class="act-date">${escapeHtml(formatDate(item.publishedAt))}</span>` : ""}
  </div>
  <a class="act-title" href="${escapeAttr(item.href)}">${escapeHtml(item.title)}</a>
  ${item.byline ? `<div class="act-byline">${escapeHtml(item.byline)}</div>` : ""}
</div>`,
    )
    .join("");

  const body = `
<section class="act-masthead">
  <div class="kicker"><span class="live"></span> Activity</div>
  <h1 class="act-h1">Everything published, in order.</h1>
  <p class="act-lede">
    Signed analyses, editorial pieces, and legacy briefs — the three places content
    actually goes live on this site — in one chronological list. Anything flagged
    <b>AI-drafted</b> was drafted with AI assistance and read by the editor before
    publication; every quote in it is checked verbatim against a stored source.
  </p>
</section>

<section class="act-list-section">
  ${
    items.length
      ? `<div class="sec-h"><span class="label">Published</span><span class="coord">${items.length} ITEM${items.length === 1 ? "" : "S"}</span></div>
  <div class="act-list">${rows}</div>`
      : emptyState("Nothing published yet.")
  }
</section>
`;

  return renderPage({
    title: "Activity · canopticon",
    description: "Everything published on canopticon.com, in chronological order.",
    body: `${body}
<style>
  .act-masthead { max-width: 720px; margin: 40px auto 0; padding: 0 24px; }
  .act-h1 { font-family: var(--serif); font-size: 32px; line-height: 1.15; margin: 12px 0 14px; color: var(--ink); text-wrap: balance; }
  .act-lede { font-family: var(--serif); font-size: 16px; line-height: 1.6; color: var(--ink-2); }
  .act-list-section { max-width: 720px; margin: 40px auto 0; padding: 0 24px 80px; }
  .act-list { display: flex; flex-direction: column; gap: 1px; background: var(--rule); border: 1px solid var(--rule); border-radius: var(--r-lg); overflow: hidden; }
  .act-row { background: var(--surface); padding: 14px 18px; }
  .act-row.act-auto { background: var(--corr-bg, rgba(196,106,83,.06)); }
  .act-row-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-bottom: 4px; }
  .act-kind { font-family: var(--mono); font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--accent-2); }
  .act-auto-flag { font-family: var(--mono); font-size: 10.5px; letter-spacing: .04em; text-transform: uppercase; color: var(--corr, #c46a53); font-weight: 600; }
  .act-date { font-family: var(--mono); font-size: 11px; color: var(--ink-mute); margin-left: auto; }
  .act-title { font-family: var(--serif); font-size: 16.5px; color: var(--ink); text-decoration: none; display: block; }
  .act-title:hover { color: var(--accent-2); }
  .act-byline { font-family: var(--mono); font-size: 11px; color: var(--ink-mute); margin-top: 3px; }
</style>`,
    activeNav: "/activity",
    zone: "activity",
  });
}
